import { MakeLogicType, actions, kea, listeners, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import api from 'lib/api'
import { lemonToast } from 'lib/lemon-ui/LemonToast'

import type { CyclotronJobInputType, HogFunctionMappingType } from '~/types'

import type { MessageTemplate } from '../../TemplateLibrary/types'

export interface SaveFunctionTemplatePayload {
    name: string
    description: string
    templateId: string
    inputs: Record<string, CyclotronJobInputType>
    mappings?: HogFunctionMappingType[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface savedFunctionTemplatesLogicValues {
    saveModalOpen: boolean
    savedFunctionTemplates: MessageTemplate[]
    savedFunctionTemplatesLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface savedFunctionTemplatesLogicActions {
    closeSaveModal: () => {
        value: true
    }
    loadSavedFunctionTemplates: () => any
    loadSavedFunctionTemplatesFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadSavedFunctionTemplatesSuccess: (
        savedFunctionTemplates: MessageTemplate[],
        payload?: any
    ) => {
        savedFunctionTemplates: MessageTemplate[]
        payload?: any
    }
    openSaveModal: () => {
        value: true
    }
    saveFunctionTemplate: ({ name, description, templateId, inputs, mappings }: any) => any
    saveFunctionTemplateFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    saveFunctionTemplateSuccess: (
        savedFunctionTemplates: MessageTemplate[],
        payload?: any
    ) => {
        savedFunctionTemplates: MessageTemplate[]
        payload?: any
    }
}

export type savedFunctionTemplatesLogicType = MakeLogicType<
    savedFunctionTemplatesLogicValues,
    savedFunctionTemplatesLogicActions
>

export const savedFunctionTemplatesLogic = kea<savedFunctionTemplatesLogicType>([
    path(['products', 'workflows', 'frontend', 'Workflows', 'hogflows', 'savedFunctionTemplatesLogic']),
    actions({
        openSaveModal: true,
        closeSaveModal: true,
    }),
    loaders(({ values }) => ({
        savedFunctionTemplates: [
            [] as MessageTemplate[],
            {
                loadSavedFunctionTemplates: async () => {
                    const response = await api.messaging.getTemplates({ type: 'function' })
                    return response.results
                },
                saveFunctionTemplate: async ({ name, description, templateId, inputs, mappings }) => {
                    const created = await api.messaging.createTemplate({
                        name,
                        description,
                        type: 'function',
                        content: {
                            templating: 'liquid',
                            function: {
                                template_id: templateId,
                                inputs,
                                ...(mappings ? { mappings } : {}),
                            },
                        },
                    })
                    lemonToast.success('Template saved to library')
                    return [...values.savedFunctionTemplates, created]
                },
            },
        ],
    })),
    reducers({
        saveModalOpen: [
            false,
            {
                openSaveModal: () => true,
                closeSaveModal: () => false,
                saveFunctionTemplateSuccess: () => false,
            },
        ],
    }),
    listeners({
        saveFunctionTemplateFailure: () => {
            lemonToast.error("Couldn't save the template. Try again, and if it keeps happening contact support.")
        },
    }),
])
